/* Minimal Markdown renderer (subset) for Vroomfogle.com chronicles pages.
 * This is intentionally tiny: headings, paragraphs, emphasis, links, lists, code blocks, and blockquotes.
 * If you later want full CommonMark support, swap this file for the official Marked bundle.
 */
(function (global) {
  function escapeHtml(s) {
    return s
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  function inline(md) {
    // code
    md = md.replace(/`([^`]+)`/g, function (_, c) {
      return '<code>' + escapeHtml(c) + '</code>';
    });
    // bold
    md = md.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
    // italics
    md = md.replace(/\*([^*]+)\*/g, '<em>$1</em>');
    // links
    md = md.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2">$1</a>');
    return md;
  }

  function parse(md) {
    const lines = md.replace(/\r\n/g, '\n').split('\n');
    const out = [];

    let inCode = false;
    let codeLang = '';
    let codeLines = [];

    let inList = false;
    let listType = null; // 'ul' or 'ol'

    function closeList() {
      if (inList) {
        out.push(`</${listType}>`);
        inList = false;
        listType = null;
      }
    }

    function flushCode() {
      if (inCode) {
        const cls = codeLang ? ` class="language-${escapeHtml(codeLang)}"` : '';
        out.push(`<pre><code${cls}>${escapeHtml(codeLines.join('\n'))}</code></pre>`);
        inCode = false;
        codeLang = '';
        codeLines = [];
      }
    }

    for (let i = 0; i < lines.length; i++) {
      const raw = lines[i];

      const fence = raw.match(/^```\s*(.*)$/);
      if (fence) {
        if (!inCode) {
          closeList();
          inCode = true;
          codeLang = (fence[1] || '').trim();
          continue;
        } else {
          flushCode();
          continue;
        }
      }

      if (inCode) {
        codeLines.push(raw);
        continue;
      }

      // headings
      const h = raw.match(/^(#{1,6})\s+(.*)$/);
      if (h) {
        closeList();
        const lvl = h[1].length;
        out.push(`<h${lvl}>${inline(h[2].trim())}</h${lvl}>`);
        continue;
      }

      // blockquote
      const bq = raw.match(/^>\s?(.*)$/);
      if (bq) {
        closeList();
        out.push(`<blockquote>${inline(bq[1])}</blockquote>`);
        continue;
      }

      // unordered list
      const ul = raw.match(/^\s*[-*]\s+(.*)$/);
      if (ul) {
        if (!inList || listType !== 'ul') {
          closeList();
          inList = true;
          listType = 'ul';
          out.push('<ul>');
        }
        out.push(`<li>${inline(ul[1].trim())}</li>`);
        continue;
      }

      // ordered list
      const ol = raw.match(/^\s*\d+\.\s+(.*)$/);
      if (ol) {
        if (!inList || listType !== 'ol') {
          closeList();
          inList = true;
          listType = 'ol';
          out.push('<ol>');
        }
        out.push(`<li>${inline(ol[1].trim())}</li>`);
        continue;
      }

      // blank line
      if (raw.trim() === '') {
        closeList();
        continue;
      }

      // paragraph
      closeList();
      out.push(`<p>${inline(raw)}</p>`);
    }

    closeList();
    flushCode();
    return out.join('\n');
  }

  global.marked = {
    parse
  };
})(window);
